#!/usr/bin/env node
// Writes src/lib/mesonet.openapi.d.ts from mesonet2's live OpenAPI spec.
// A manual step (`npm run gen:api`), never run in CI: the build should not
// depend on the live API being up, and a spec change deserves a reviewed diff.
import { writeFileSync } from 'node:fs';
import openapiTS, { astToString } from 'openapi-typescript';
import { OPENAPI_URL } from '../src/lib/mesonet.ts';

const OUT = new URL('../src/lib/mesonet.openapi.d.ts', import.meta.url);

const header = `// GENERATED by openapi-typescript from ${OPENAPI_URL}.
// Do not edit by hand. Regenerate with \`npm run gen:api\` and review the diff.
`;

// The API serialises its enums from unordered sets, so each fetch lists them
// in a different order. Sort them, or every regeneration is a noisy diff.
const sortEnums = (node) => {
  if (Array.isArray(node)) return node.forEach(sortEnums);
  if (!node || typeof node !== 'object') return;
  if (Array.isArray(node.enum)) node.enum.sort();
  Object.values(node).forEach(sortEnums);
};

const res = await fetch(OPENAPI_URL);
if (!res.ok) throw new Error(`gen-api: HTTP ${res.status} from ${OPENAPI_URL}`);
const spec = await res.json();
sortEnums(spec);

const ast = await openapiTS(spec);
writeFileSync(OUT, header + '\n' + astToString(ast));
console.log(`gen-api: wrote ${OUT.pathname}`);
